<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.405" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/parse_binlog.cs << 'CSEOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? w.ToString()));
});

Console.WriteLine("=== ERRORS ===");
foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine("\n=== WARNINGS (WarningsAsErrors or notable) ===");
foreach (var g in warnings.GroupBy(w => w.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g.Take(10)) {
        Console.WriteLine($"  [{w.code}] {w.message}");
    }
    if (g.Count() > 10) Console.WriteLine($"  ... and {g.Count()-10} more");
}

// Also check for failed targets
Console.WriteLine("\n=== FAILED PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Succeeded) {
        Console.WriteLine($"  FAILED: {p.Name} (TargetFramework: {p.TargetFramework})");
    }
});
