using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show source file contents from the log if available
Console.WriteLine("=== SOURCE CONTEXT ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name == "Services.csproj") {
        Console.WriteLine($"Project: {p.Name}");
        p.VisitAllChildren<Item>(i => {
            Console.WriteLine($"  Item: {i.Name} = {i.Text}");
        });
        p.VisitAllChildren<Property>(prop => {
            if (prop.Name.Contains("PackageReference") || prop.Name.Contains("Reference") || prop.Name == "ProjectDir" || prop.Name == "TargetFramework")
                Console.WriteLine($"  Prop: {prop.Name} = {prop.Value}");
        });
        // Show all named nodes
        p.VisitAllChildren<NamedNode>(n => {
            if (n.Name != null && (n.Name.Contains("PackageReference") || n.Name.Contains("Newtonsoft") || n.Name.Contains("Reference")))
                Console.WriteLine($"  NamedNode: {n.GetType().Name} - {n.Name} = {n}");
        });
    }
});

// Also look at restore
Console.WriteLine("\n=== NUGET RESTORE INFO ===");
build.VisitAllChildren<Target>(t => {
    if (t.Name != null && t.Name.Contains("Restore")) {
        var proj = "";
        var node = t.Parent;
        while (node != null) {
            if (node is Project p2) { proj = p2.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  Target: {t.Name} in {proj}");
        t.VisitAllChildren<Message>(m => {
            if (m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("error") || m.Text.Contains("warn")))
                Console.WriteLine($"    {m.Text}");
        });
    }
});

// Show all warnings
Console.WriteLine("\n=== ALL WARNINGS ===");
build.VisitAllChildren<Warning>(w => {
    Console.WriteLine($"  [{w.Code}] {w.Text}");
});

// Check for project references
Console.WriteLine("\n=== PROJECT STRUCTURE ===");
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "PackageReference" || ai.Name == "ProjectReference") {
        var proj = "";
        var node = ai.Parent;
        while (node != null) {
            if (node is Project p3) { proj = p3.Name; break; }
            node = node.Parent;
        }
        foreach (var item in ai.Children.OfType<Item>()) {
            Console.WriteLine($"  {proj} -> {ai.Name}: {item.Text}");
        }
    }
});
